:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color-scheme: light;
  background: #f6f8fb;
  color: #10213d;
}

* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; background: #f6f8fb; color: #10213d; }
button, textarea { font: inherit; }
button { cursor: pointer; }
[hidden] { display: none !important; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }

/* The foundation controls stay in the document for the trusted runtime, but daily UX lives in Settings. */
.patch-controls { display: none !important; }

#app { min-height: 100vh; }
.lighthouse-shell { min-height: 100vh; display: grid; grid-template-rows: auto 1fr auto; background: #fff; }
.lighthouse-topbar { min-height: 3.5rem; display: flex; align-items: center; justify-content: space-between; padding: env(safe-area-inset-top, 0) 1rem 0; border-bottom: 1px solid #edf0f5; background: rgba(255,255,255,.96); }
.lighthouse-brand { display: flex; align-items: center; gap: .55rem; }
.lighthouse-brand h1 { margin: 0; font-size: .95rem; letter-spacing: .08em; font-weight: 750; }
.lighthouse-mark { display: grid; place-items: center; width: 1.7rem; height: 1.7rem; border-radius: .55rem; background: #10213d; color: #fff; }
.icon-button { width: 2.4rem; height: 2.4rem; border: 0; border-radius: 50%; background: transparent; color: #10213d; font-size: 1.15rem; }
.icon-button:active { background: #eef2f7; }

.chat-stage { position: relative; min-height: 0; overflow: hidden; }
.chat-log { height: 100%; overflow-y: auto; padding: 1.1rem 1rem 6rem; display: flex; flex-direction: column; gap: .75rem; }
.empty-chat { margin: auto; text-align: center; color: #9aa6b8; }
.empty-mark { margin: 0 auto .85rem; width: 4rem; height: 4rem; display: grid; place-items: center; border-radius: 1.35rem; background: #f4f7fb; color: #c4ccd8; font-size: 1.8rem; }
.empty-chat p { margin: 0; font-size: .92rem; }
.message { max-width: min(31rem, 84%); padding: .72rem .9rem; border-radius: 1.1rem; line-height: 1.45; white-space: pre-wrap; overflow-wrap: anywhere; }
.message-user { align-self: flex-end; background: #10213d; color: #fff; border-bottom-right-radius: .35rem; }
.message-lighthouse { align-self: flex-start; background: #f0f3f7; color: #28374f; border-bottom-left-radius: .35rem; }

.chat-composer { position: sticky; bottom: 0; display: grid; grid-template-columns: 1fr auto; gap: .55rem; padding: .7rem max(1rem, env(safe-area-inset-right)) calc(.7rem + env(safe-area-inset-bottom, 0)) max(1rem, env(safe-area-inset-left)); border-top: 1px solid #edf0f5; background: rgba(255,255,255,.97); }
.chat-composer textarea { resize: none; min-height: 2.75rem; max-height: 8rem; border: 1px solid #dfe5ee; border-radius: 1.4rem; padding: .72rem 1rem; outline: none; background: #fff; color: #10213d; }
.chat-composer textarea:focus { border-color: #8da4c4; box-shadow: 0 0 0 3px rgba(62,101,151,.1); }
.send-button { width: 2.75rem; height: 2.75rem; border: 0; border-radius: 50%; background: #10213d; color: #fff; }

.transient-notice { position: absolute; left: 50%; bottom: 1rem; transform: translateX(-50%); max-width: calc(100% - 2rem); padding: .55rem .8rem; border-radius: 999px; background: #10213d; color: #fff; font-size: .82rem; box-shadow: 0 10px 30px rgba(16,33,61,.18); }
.system-alert { position: fixed; z-index: 30; top: calc(1rem + env(safe-area-inset-top, 0)); left: 1rem; right: 1rem; display: flex; gap: 1rem; align-items: flex-start; justify-content: space-between; padding: .9rem 1rem; border: 1px solid #e8b8b8; border-radius: 1rem; background: #fff4f4; color: #8b2222; box-shadow: 0 14px 40px rgba(83,31,31,.16); }
.system-alert strong { display: block; margin-bottom: .2rem; }
.system-alert p { margin: 0; line-height: 1.4; font-size: .88rem; }
.system-alert button { border: 0; background: transparent; color: inherit; font-weight: 700; }

.settings-sheet { position: fixed; z-index: 20; inset: 0; background: #f6f8fb; overflow-y: auto; }
.settings-card { min-height: 100%; max-width: 42rem; margin: 0 auto; background: #fff; }
.settings-head { display: flex; align-items: center; gap: .7rem; min-height: 4.2rem; padding: env(safe-area-inset-top, 0) 1rem 0; border-bottom: 1px solid #edf0f5; }
.settings-head small, .settings-section small { color: #8a97a9; font-size: .72rem; text-transform: uppercase; letter-spacing: .08em; }
.settings-head h2, .settings-section h3 { margin: .08rem 0 0; }
.settings-head h2 { font-size: 1.05rem; }
.settings-section { margin: 1rem; padding: 1rem; border: 1px solid #e7ebf1; border-radius: 1.1rem; background: #fff; }
.settings-title-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; }
.settings-section h3 { font-size: 1rem; }
.version-chip { flex: none; padding: .35rem .55rem; border-radius: 999px; background: #eef4f1; color: #27664a; font-size: .8rem; font-weight: 700; }
.settings-copy { margin: .8rem 0 1rem; color: #647187; line-height: 1.5; font-size: .88rem; }
.settings-actions { display: grid; gap: .6rem; }
.primary-button, .danger-button { min-height: 2.8rem; border-radius: .8rem; padding: .65rem .9rem; font-weight: 700; }
.primary-button { border: 0; background: #10213d; color: #fff; }
.danger-button { border: 1px solid #e2a9a9; background: #fff; color: #a02d2d; }

@media (min-width: 700px) {
  .lighthouse-shell { width: min(44rem, 100%); margin: 0 auto; border-inline: 1px solid #edf0f5; }
}

